import styled from '@emotion/styled';

export const Container = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
  width: '100%',
  margin: '0 auto',
});

export const ValueContainer = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '6px',
  flex: 1,
});

export const MultiValueRemove = styled.div({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  color: '#141414',
  backgroundColor: 'white',
  borderRadius: '50%',
  width: '16px',
  height: '16px',

  '&:hover': {
    color: '#141414',
    backgroundColor: 'white',
  },

  svg: {
    width: '10px',
    height: '10px',
  },
});

type ChipSize = 'small' | 'medium' | 'large';

interface StyledChipsProps {
  $size?: ChipSize;
  $disabled?: boolean;
}

export const StyledChips = styled.div<StyledChipsProps>(
  ({ $size, $disabled }) => ({
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#fff1c2',
    borderRadius: '512px',
    margin: '2px 4px',
    padding: '8px 12px',
    gap: '4px',

    ...($size === 'small' && { height: '24px' }),
    ...($size === 'medium' && { height: '30px' }),
    ...($size === 'large' && { height: '40px' }),
    ...($disabled && {
      backgroundColor: '#ffffff',
      borderColor: '#14141429',
    }),

    '&:hover': {
      backgroundColor: '#fff8e0',
    },
  }),
);

interface StyledChipsPlaceholderProps {
  $size?: ChipSize;
}

export const StyledChipsPlaceholder = styled.div<StyledChipsPlaceholderProps>(
  ({ $size }) => ({
    width: '16px',
    height: '16px',
    fontSize: '14px',
    ...($size === 'small' && { fontSize: '14px' }),
    ...($size === 'medium' && { fontSize: '16px' }),
    ...($size === 'large' && { fontSize: '16px' }),
  }),
);
